def build_segment_tree(n, p_values):
    tree = [1.0] * (2 * n)
    def build(idx, l, r):
        if l == r:
            tree[idx] = p_values[l-1]
        else:
            mid = (l + r) // 2
            build(2 * idx, l, mid)
            build(2 * idx + 1, mid + 1, r)
            tree[idx] = tree[2 * idx] * tree[2 * idx + 1]
    build(1, 1, n)
    return tree

def update_segment_tree(tree, n, p_values, l, r, idx):
    tree[idx] = p_values[l-1]
    idx >>= 1
    while idx >= 1:
        tree[idx] = tree[2 * idx] * tree[2 * idx + 1]
        idx >>= 1

def query_segment_tree(tree, n, l, r):
    def query(idx, l, r, ql, qr):
        if ql <= l and r <= qr:
            return tree[idx]
        mid = (l + r) // 2
        if qr <= mid:
            return query(2 * idx, l, mid, ql, qr)
        elif ql > mid:
            return query(2 * idx + 1, mid + 1, r, ql, qr)
        else:
