    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1
        matrix = lines[idx:idx + n]
        idx += n

        count = 0

        # Count axis-aligned squares
        for size in range(2, min(n, m) + 1):
            for r in range(n - size + 1):
                for c in range(m - size + 1):
                    # Check border is all 1s
                    border_ok = True
                    # Top and bottom rows
                    if any(matrix[r][j] != '1' for j in range(c, c + size)):
                        border_ok = False
                    elif any(matrix[r + size - 1][j] != '1' for j in range(c, c + size)):
                        border_ok = False
                    # Left and right columns
                    elif any(matrix[i][c] != '1' for i in range(r, r + size)):
                        border_ok = False
                    elif any(matrix[i][c + size - 1] != '1' for i in range(r, r + size)):
                        border_ok = False

                    if not border_ok:
                        continue

                    # Check no foreign 1s touching the square (by side or corner)
                    touching = False
                    for i in range(r - 1, r + size):
                        for j in range(c - 1, c + size):
                            if (i == r - 1 or i == r + size) and c <= j < c + size:
                                if matrix[i][j] == '1':
                                    touching = True
                                    break
                            elif (j == c - 1 or j == c + size) and r <= i < r + size:
                                if matrix[i][j] == '1':
                                    touching = True
                                    break

                    if not touching:
                        count += 1

        # Count diamond (diagonal) squares
        for d in range(1, min(n, m) // 2 + 2):
            for r in range(1, n - 1):
                for c in range(1, m - 1):
                    # Check border at Manhattan distance d from center
                    border_ok = True
                    # Check all border positions
                    for i in range(r - d, r + d + 1):
                        for j in range(c - d, c + d + 1):
                            if abs(i - r) + abs(j - c) == d:
                                if matrix[i][j] != '1':
                                    border_ok = False
                                    break
                        if not border_ok:
                            break

                    if not border_ok:
                        continue

                    # Check no foreign 1s touching the diamond (by side or corner)
                    touching = False
                    for i in range(r - 2, r + d + 2):
                        for j in range(c - 2, c + d + 2):
                            if 0 <= i < n and 0 <= j < m:
                                if abs(i - r) + abs(j - c) != d:
                                    if matrix[i][j] == '1':
                                        # Check if this cell touches the diamond
                                        # Cell touches if it's adjacent to border cell
                                        for bi in range(r - d, r + d + 1):
                                            for bj in range(c - d, c + d + 1):
                                                if abs(bi - r) + abs(bj - c) == d:
                                                    # Check if (i,j) is adjacent to (bi,bj)
                                                    if abs(i - bi) <= 1 and abs(j - bj) <= 1:
                                                        touching = True
                                                        break
                                            if touching:
                                                break
                        if touching:
                            break

                    if not touching:
                        count += 1

