def actual_solution(input_str):
    """
    Solve the polygon triangulation problem using dynamic programming.
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        points.append((x, y))

    MOD = 1000000007

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def point_in_triangle(a, b, c, p):
        cp1 = cross_product(a, b, p)
        cp2 = cross_product(b, c, p)
        cp3 = cross_product(c, a, p)

        all_pos = (cp1 > 0 and cp2 > 0 and cp3 > 0)
        all_neg = (cp1 < 0 and cp2 < 0 and cp3 < 0)

        return all_pos or all_neg

    if n < 3:
        return "0\n"

    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][(i + 1) % n] = 1

    for length in range(2, n):
        for i in range(n - length):
            j = i + length
            for k in range(i + 1, j):
                cp = cross_product(points[i], points[k], points[j])
                if cp == 0:
                    continue

                valid = True
                for p in range(n):
                    if p != i and p != k and p != j:
                        if point_in_triangle(points[i], points[k], points[j], points[p]):
                            valid = False
                            break

                if valid:
                    dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    return f"{dp[0][n - 1] % MOD}\n"


