#!/usr/bin/env python3
import sys
from collections import defaultdict

def solution(input_text):
    try:
        lines = input_text.strip().split('\n')
        if not lines:
            return "IMPOSSIBLE\n"
        n, c = map(int, lines[0].split())
        constraints = []
        for i in range(1, min(c, len(lines) - 1) + 1):
            if i < len(lines):
                parts = lines[i].split()
                if len(parts) >= 3:
                    ai, bi = int(parts[0]), int(parts[1])
                    direction = parts[2]
                    constraints.append((ai, bi, direction))
    except Exception:
        return "IMPOSSIBLE\n"

    # Check basic pre-order constraint: all ai < bi
    for ai, bi, direction in constraints:
        if ai >= bi:
            return "IMPOSSIBLE\n"

    # If no constraints, any tree works - use simple right spine
    if not constraints:
        # Right spine always works: in-order = 1,2,...,n
        return " ".join(str(i) for i in range(1, n + 1)) + "\n"

    # Build graph for topological sort on in-order
    # LEFT: bi appears before ai in in-order (bi -> ai)
    # RIGHT: ai appears before bi in in-order (ai -> bi)
    graph = defaultdict(list)
    in_degree = defaultdict(int)
    all_nodes = set(range(1, n + 1))

    for ai, bi, direction in constraints:
        if direction == "LEFT":
            graph[bi].append(ai)
            in_degree[ai] += 1
        else:
            graph[ai].append(bi)
            in_degree[bi] += 1

    # Topological sort
    queue = [node for node in all_nodes if node not in in_degree or in_degree[node] == 0]
    queue.sort()  # Deterministic
    topo_order = []

    while queue:
        node = queue.pop(0)
        topo_order.append(node)
        for neighbor in sorted(graph[node]):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Cycle detected
    if len(topo_order) != n:
        return "IMPOSSIBLE\n"

    in_order = topo_order
    in_pos = {val: i for i, val in enumerate(in_order)}

    # Build tree from in-order and pre-order (1,2,...,n)
    def build_tree(root_label, in_sub):
        if not in_sub or root_label > n:
            return None
        try:
            root_pos = in_sub.index(root_label)
        except ValueError:
            return None

        left_in = in_sub[:root_pos]
        right_in = in_sub[root_pos + 1:]

        left_child = build_tree(root_label + 1, left_in)
        right_start = root_label + len(left_in) + 1
        right_child = build_tree(right_start, right_in) if right_in else None

        return (root_label, left_child, right_child)

    tree = build_tree(1, in_order)
    if tree is None:
        return "IMPOSSIBLE\n"
    root_label, left_child, right_child = tree

    # Verify constraints
    def in_left_subtree(node, target):
        p_node = in_pos[node]
        p_target = in_pos[target]
        return p_target < p_node

    def in_right_subtree(node, target):
        p_node = in_pos[node]
        p_target = in_pos[target]
        return p_target > p_node

    for ai, bi, direction in constraints:
        if direction == "LEFT":
            if not in_left_subtree(ai, bi):
                return "IMPOSSIBLE\n"
        else:
            if not in_right_subtree(ai, bi):
                return "IMPOSSIBLE\n"

    # Output in-order traversal
    return " ".join(str(x) for x in in_order) + "\n"


