def get_block_length(n):
    """Get length of block n (concatenation of numbers 1 to n)"""
    if n == 0:
        return 0

    length = 0
    # Count digits by number ranges
    for d in range(1, 20):
        start = 10**(d-1) if d > 1 else 1
        end = 10**d - 1

