        # prefix_min[i] = min fall time for icicle at position 1..i
        # suffix_min[i] = min fall time for icicle at position i..n
        prefix_min = [float('inf')] * (n + 1)
        suffix_min = [float('inf')] * (n + 1)

        for i in range(n):
            val = fall_times[i]
            prefix_min[i + 1] = min(prefix_min[i], val)

        for i in range(n - 1, -1, -1):
            val = fall_times[i]
            suffix_min[i] = min(suffix_min[i + 1], val)

        # Check each time t
        max_time = 400000  # sufficient upper bound
        for t in range(1, max_time + 1):
            k_pos = t + 1  # Krakozyabra position at time t
            if k_pos > n + 1:
