    # Build conflict graph: two roads conflict if they cross when both inside or both outside
    conflict = [[False] * m for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            a1, b1 = roads[i]
            a2, b2 = roads[j]
            # Two roads (a1,b1) and (a2,b2) cross if they interleave: a1 < a2 < b1 < b2
            if a1 < a2 < b1 < b2:
                conflict[i][j] = conflict[j][i] = True

    # Check if bipartite using BFS (2-coloring)
    color = [-1] * m
    for start in range(m):
        if color[start] == -1:
            color[start] = 0
            queue = deque([start])
            while queue:
                u = queue.popleft()
                for v in range(m):
                    if conflict[u][v]:
                        if color[v] == -1:
                            color[v] = 1 - color[u]
                            queue.append(v)
                        elif color[v] == color[u]:
                            return "Impossible\n"

    result = ''.join('i' if color[i] == 0 else 'o' for i in range(m))
    return result + '\n'

