def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:n+1)]

    # Check for immediate conflicts (pre-colored adjacent vertices with same color)
    for r in range(n):
        for c in range(m):
            if grid[r][c] != '0':
                val = grid[r][c]
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
