                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if grid[nr][nc] == val:
                                return '0'

    # Pattern: color(r, c) = mapping[(2*r + c) % 4]
    # This is a valid 4-coloring for King's graph
    perms = list(itertools.permutations([1, 2, 3, 4]))

    for perm in perms:
        valid = True
        for r in range(n):
            for c in range(m):
                if grid[r][c] != '0':
                    idx = (2 * r + c) % 4
                    if grid[r][c] != str(perm[idx]):
                        valid = False
                        break
            if not valid:
                break

        if valid:
            result = []
            for r in range(n):
                row = []
