        # For large length, we use math
        # But actually let's just compute what fits
        result_str = val_str * length
        return int(result_str) % mod, total_len

    # Final parse
    result = parse_expr()

    # Handle the case where there might be more digits after processing
    while pos < len(tokens):
        result = concat_nums(result, tokens[pos])
        pos += 1

    # Return as string
    return str(result[0]) + '\n'
